const cv=document.getElementById('c'),g=cv.getContext('2d');
const W=540,H=960,TOP=274,LANE=110,N=6,BOT=TOP+LANE*N,TILE=1080,MID=TOP+LANE*3;
// centro de cada faixa (para usar na Parte 2, dos carros)
const LANE_Y=Array.from({length:2*N-1},(_,j)=>TOP+LANE/2+(LANE/2)*j);
let cam=0,speed=300,paused=false,fin=null,t=0;

// asfalto: textura detalhada (remendos, rachaduras, marcas de pneu, óleo, juntas), feita uma vez em alta resolução
const tile=document.createElement('canvas');tile.width=TILE*2;tile.height=LANE*N*2;
{
  const p=tile.getContext('2d'),h=LANE*N,R=Math.random;p.scale(2,2);
  const wrap=fn=>{for(const d of[-TILE,0,TILE])fn(d)};
  p.fillStyle='#3a3e3d';p.fillRect(0,0,TILE,h);
  for(let k=0;k<N;k++){p.fillStyle=R()<.5?'rgba(255,255,255,'+(.012+R()*.02)+')':'rgba(0,0,0,'+(.03+R()*.05)+')';p.fillRect(0,k*LANE,TILE,LANE)}
  for(let i=0;i<16;i++){
    const x=R()*TILE,y=R()*(h-100),w=110+R()*200,hh=36+R()*70,dk=R()<.6;
    wrap(d=>{p.fillStyle=dk?'rgba(0,0,0,.11)':'rgba(255,255,255,.04)';p.fillRect(x+d,y,w,hh);p.strokeStyle='rgba(0,0,0,.22)';p.lineWidth=1;p.strokeRect(x+d+.5,y+.5,w,hh)});
  }
  for(let i=0;i<46;i++){
    const x=R()*TILE,y=R()*h,rx=30+R()*90,ry=8+R()*22,a=.1+R()*.16;
    wrap(d=>{
      const gr=p.createRadialGradient(x+d,y,0,x+d,y,rx);gr.addColorStop(0,'rgba(15,18,17,'+a+')');gr.addColorStop(1,'rgba(15,18,17,0)');
      p.save();p.translate(x+d,y);p.scale(1,ry/rx);p.translate(-(x+d),-y);p.fillStyle=gr;p.fillRect(x+d-rx,y-rx,rx*2,rx*2);p.restore();
    });
  }
  for(let k=0;k<N;k++)for(const off of[-24,24]){
    let x=R()*260;
    for(;;){
      const len=160+R()*340;if(x+len>TILE-10)break;
      const y=k*LANE+LANE/2+off+(R()-.5)*3,gr=p.createLinearGradient(x,0,x+len,0);
      gr.addColorStop(0,'rgba(0,0,0,0)');gr.addColorStop(.2,'rgba(0,0,0,.2)');gr.addColorStop(.8,'rgba(0,0,0,.2)');gr.addColorStop(1,'rgba(0,0,0,0)');
      p.fillStyle=gr;p.fillRect(x,y-4,len,8);x+=len+R()*260;
    }
  }
  for(let i=0;i<9;i++){
    const x=R()*TILE,y=(Math.floor(R()*N)+.5)*LANE+(R()-.5)*50,rx=14+R()*16,ry=6+R()*5;
    wrap(d=>{const gr=p.createRadialGradient(x+d,y,0,x+d,y,rx);gr.addColorStop(0,'rgba(0,0,0,.45)');gr.addColorStop(.7,'rgba(20,24,30,.25)');gr.addColorStop(1,'rgba(0,0,0,0)');
      p.save();p.translate(x+d,y);p.scale(1,ry/rx);p.translate(-(x+d),-y);p.fillStyle=gr;p.fillRect(x+d-rx,y-rx,rx*2,rx*2);p.restore()});
  }
  for(let i=0;i<24;i++){
    let x=R()*TILE,y=R()*h,a=R()*6;const pts=[[x,y]];
    for(let s=0;s<14;s++){a+=(R()-.5)*1.2;x+=Math.cos(a)*(5+R()*7);y+=Math.sin(a)*(5+R()*7);pts.push([x,y])}
    wrap(d=>{p.beginPath();pts.forEach((q,j)=>j?p.lineTo(q[0]+d,q[1]):p.moveTo(q[0]+d,q[1]));p.strokeStyle='rgba(8,8,8,.55)';p.lineWidth=1.2;p.stroke();p.strokeStyle='rgba(255,255,255,.07)';p.lineWidth=.6;p.stroke()});
  }
  for(let x=135;x<TILE;x+=270){p.fillStyle='rgba(0,0,0,.5)';p.fillRect(x,0,2,h);p.fillStyle='rgba(255,255,255,.07)';p.fillRect(x+2,0,1,h)}
  for(let i=0;i<16000;i++){p.fillStyle=R()<.5?'rgba(255,255,255,.045)':'rgba(0,0,0,.12)';p.fillRect(R()*TILE,R()*h,1+R()*.9,1+R()*.9)}
  for(let i=0;i<900;i++){p.fillStyle='rgba(205,205,200,'+(.12+R()*.18)+')';p.fillRect(R()*TILE,R()*h,1+R(),1+R())}
  let s=p.createLinearGradient(0,0,0,16);s.addColorStop(0,'rgba(0,0,0,.28)');s.addColorStop(1,'rgba(0,0,0,0)');p.fillStyle=s;p.fillRect(0,0,TILE,16);
  s=p.createLinearGradient(0,h-16,0,h);s.addColorStop(0,'rgba(0,0,0,0)');s.addColorStop(1,'rgba(0,0,0,.28)');p.fillStyle=s;p.fillRect(0,h-16,TILE,16);
}
const SHIRTS=['#e23a2e','#ffd400','#1f5fd1','#0a9b3c','#f4f4f4','#ff7a1a','#8f56e8'];
const SKIN=['#e0b48a','#c68b5c','#8d5a3b','#f1c9a5'];

const HZ=TOP;
const bg=new Image();let bgReady=false;bg.onload=()=>{bgReady=true};bg.src='data:image/jpeg;base64,';
function drawBg(){const th=HZ,tw=bg.width*th/bg.height;let x=-((cam*.6)%tw);for(;x<W;x+=tw)g.drawImage(bg,x,0,tw+1,th)}
function rnd(i,s){const x=Math.sin(i*127.1+s*311.7)*43758.5453;return x-Math.floor(x)}
const WALLS=['#f2d16b','#e8856b','#7fc4b0','#ece4cf','#9db7e8','#d98aa8'];
function scenery(){
  if(bgReady){drawBg();return}
  let s=g.createLinearGradient(0,0,0,HZ);s.addColorStop(0,'#4fa8ec');s.addColorStop(1,'#cfeaf8');
  g.fillStyle=s;g.fillRect(0,0,W,HZ);
  // nuvens (andam bem devagar)
  g.fillStyle='rgba(255,255,255,.85)';
  let k=Math.floor(cam*.08/260)-1;
  for(let i=k;i<k+4;i++){
    const x=i*260+60*rnd(i,1)-cam*.08,y=18+rnd(i,2)*50;
    for(const[dx,dy,r]of[[0,0,16],[18,-6,20],[40,0,15]]){g.beginPath();g.arc(x+dx,y+dy,r,0,7);g.fill()}
  }
  // prédios lá de trás (andam devagar)
  k=Math.floor(cam*.25/70)-1;
  for(let i=k;i<k+10;i++){
    const w=56+rnd(i,3)*10,h=60+rnd(i,4)*60,x=i*70-cam*.25;
    g.fillStyle='hsl('+(200+rnd(i,5)*40|0)+',28%,'+(64+rnd(i,6)*8|0)+'%)';g.fillRect(x,HZ-h,w,h);
    g.fillStyle='rgba(255,255,255,.28)';
    for(let yy=HZ-h+8;yy<HZ-10;yy+=14)for(let xx=x+6;xx<x+w-8;xx+=13)g.fillRect(xx,yy,6,7);
  }
  // casas e lojas da frente (andam mais rápido)
  k=Math.floor(cam*.6/112)-1;
  for(let i=k;i<k+7;i++){
    const x=i*112-cam*.6+4,w=100,h=56+rnd(i,7)*40,ty=rnd(i,8)*3|0,y=HZ-h;
    g.fillStyle=WALLS[rnd(i,9)*WALLS.length|0];g.fillRect(x,y,w,h);
    g.fillStyle='rgba(0,0,0,.12)';g.fillRect(x+w-10,y,10,h);
    if(ty===0){g.fillStyle='#a8452e';g.beginPath();g.moveTo(x-5,y);g.lineTo(x+w+5,y);g.lineTo(x+w/2,y-24);g.fill()}
    else{g.fillStyle='rgba(0,0,0,.28)';g.fillRect(x-3,y-6,w+6,6)}
    for(let r=0;r<Math.floor((h-30)/28);r++)for(let q=0;q<3;q++){
      g.fillStyle='#cfe8ff';g.fillRect(x+10+q*30,y+8+r*28,18,16);
      g.fillStyle='rgba(0,0,0,.3)';g.fillRect(x+10+q*30,y+22+r*28,18,2);
    }
    g.fillStyle='#5a3a24';g.fillRect(x+w/2-8,HZ-22,16,22);
    if(ty===2)for(let q=0;q<6;q++){g.fillStyle=q%2?'#fff':'#d63a2e';g.fillRect(x+w/2-24+q*8,HZ-34,8,10)}
  }
}
function draw(){
  g.setTransform(SC,0,0,SC,0,0);
  g.fillStyle='#0f1318';g.fillRect(-20,-20,W+40,H+40);
  if(shake>0)g.translate((Math.random()-.5)*10*shake,(Math.random()-.5)*7*shake);
  g.fillStyle='#0f1318';g.fillRect(0,0,W,H);
  scenery();


  drawRoad();

  // meio-fio de baixo com as plaquinhas
  g.fillStyle='#d6cdaa';g.fillRect(0,BOT,W,H-BOT);
  g.fillStyle='#a79f7c';g.fillRect(0,BOT+2,W,3);
  const j0=Math.floor(cam/270)-1;
  for(let j=j0;j<j0+4;j++){
    const sx=j*270+120-cam;
    g.fillStyle='#4a4437';g.fillRect(sx,BOT+9,40,11);
    g.fillStyle='#d8b43a';g.fillRect(sx+10,BOT+12,20,5);
  }

  // linha de chegada quadriculada
  if(fin!==null){
    const sx=fin-cam;
    if(sx>-40&&sx<W+40){
      g.fillStyle='rgba(0,0,0,.28)';g.fillRect(sx+28,TOP,7,LANE*N);
      for(let r=0;r<Math.ceil(LANE*N/14);r++)for(let c=0;c<2;c++){
        g.fillStyle=(r+c)%2?'#1f2c25':'#efe9d2';
        g.fillRect(sx+c*14,TOP+r*14,14,Math.min(14,LANE*N-r*14));
      }
    }else if(sx<-60)fin=null;
  }
  if(startX!==null){
    const sx=startX-cam;
    if(sx>-40&&sx<W+40){
      g.fillStyle='rgba(0,0,0,.28)';g.fillRect(sx+28,TOP,7,LANE*N);
      for(let r=0;r<Math.ceil(LANE*N/14);r++)for(let c=0;c<2;c++){
        g.fillStyle=(r+c)%2?'#1f2c25':'#efe9d2';
        g.fillRect(sx+c*14,TOP+r*14,14,Math.min(14,LANE*N-r*14));
      }
    }
  }
  drawFx();
  drawCars();
  drawVignette();
  drawHud();
  drawLobbyUi();
  drawNote();
  drawStartUi();
  drawResult();
  drawConfetti();
  if(flash>0){g.fillStyle='rgba(255,255,255,'+(flash*.6)+')';g.fillRect(-20,-20,W+40,H+40)}
}

