function makePH(){
  // carros provisórios desenhados por código, só para o jogo funcionar enquanto não há imagens
  return['#d33','#2f7fe0','#2aa86b','#e0b020','#e8e8e8','#333'].map(col=>{
    const c=document.createElement('canvas');c.width=300;c.height=120;const p=c.getContext('2d');
    p.fillStyle=col;p.beginPath();p.roundRect(8,52,284,44,16);p.fill();
    p.beginPath();p.moveTo(70,52);p.lineTo(100,18);p.lineTo(206,18);p.lineTo(244,52);p.closePath();p.fill();
    p.fillStyle='rgba(160,210,255,.85)';
    p.beginPath();p.moveTo(82,52);p.lineTo(106,26);p.lineTo(148,26);p.lineTo(148,52);p.closePath();p.fill();
    p.beginPath();p.moveTo(156,52);p.lineTo(156,26);p.lineTo(200,26);p.lineTo(228,52);p.closePath();p.fill();
    p.fillStyle='#ffe66b';p.fillRect(280,60,10,8);p.fillStyle='#d11';p.fillRect(10,60,8,8);
    for(const x of[72,230]){p.fillStyle='#111';p.beginPath();p.arc(x,96,22,0,7);p.fill();p.fillStyle='#bbb';p.beginPath();p.arc(x,96,11,0,7);p.fill()}
    return c;
  });
}
const imgs=SPR.length?SPR.map(u=>{const i=new Image();i.src=u;return i}):makePH();
const MAXC=100,LEN=16000,CAMX=330,ORD=[2,3,1,4,0,5],NL=2*N-1;
const colorFor=i=>i<8?COL[i]:'hsl('+Math.round((i*137.508)%360)+',75%,58%)';
const GIFTS=['presente pequeno','presente médio','presente grande'],BOOST=[40,90,180];
const COL=['#ff3b5c','#ffb400','#22c58b','#3fa7ff','#8f56e8','#f26a1b','#d9dde3','#e84fb8'];
let cars=[],queue=[],rstate='lobby',count=45,doneT=0,winner=null,ci=0,raceX0=0,startX=null;
function modelOf(k){for(let m=0;m<MODEL_K.length;m++)if(MODEL_K[m].includes(k))return m;return -1}
function setModel(c,k){c.k=k;c.spr=imgs[k];c.cn=CARNAME[k];c.L=CARLEN[k]||150;c.rl=CARWH[k]?(CARWH[k][0][2]+CARWH[k][1][2])/2*(c.L/CARTW[k]):0;c.mi=modelOf(k)}
function pickK(m){return m>=0&&MODEL_K[m]&&MODEL_K[m].length?MODEL_K[m][Math.random()*MODEL_K[m].length|0]:Math.random()*imgs.length|0}
function mkCar(name,m){
  const i=cars.length,row=Math.floor(i/11),s=i%11,lane=s<6?2*ORD[s]:2*(s-6)+1;
  const c={name,wa:Math.random()*6,dw:0,color:colorFor(ci++),d:raceX0+330-row*180-(s<6?s*8:90+(s-6)*8),v:0,base:380+Math.random()*60,ph:Math.random()*6,boost:0,lane,y:LANE_Y[lane],lt:Math.random()};
  setModel(c,pickK(m));return c;
}
function join(u,text){
  u=Array.from(String(u||'').trim()).slice(0,20).join('');if(!u)return null;
  const m=modelFrom(text);
  let c=cars.find(x=>x.name===u);
  if(c){
    if(m>=0&&rstate==='lobby'&&c.mi!==m){   // trocou de modelo na largada: mantém a mesma cor (posição na lista)
      const pos=Math.max(0,MODEL_K[c.mi].indexOf(c.k));setModel(c,MODEL_K[m][Math.min(pos,MODEL_K[m].length-1)]);notify('swap',u,c.cn);
    }
    return c;
  }
  if(rstate==='lobby'&&cars.length<MAXC){if(!cars.length)raceX0=cam;startX=raceX0+360;c=mkCar(u,m);cars.push(c);feed(u,'entrou na pista');notify('join',u,c.cn);return c}
  if(m>=0)pref.set(u,m);
  if(!queue.includes(u)){if(queue.length<1000)queue.push(u);feed(u,'entra na próxima corrida');notify('queue',u)}
  return null;
}
function handle(e){
  if(!e||!e.user)return;const c=join(e.user,e.type==='comment'?e.text:'');
  if(e.type==='like'&&c){const n=Math.max(1,e.count|0);if(rstate==='racing')c.boost=Math.min(260,c.boost+n*1.6);feed(c.name,'+'+n+' curtidas, acelerou');notify('like',c.name,n);if(rstate==='racing'&&n>=15){fprio=c;if(fage>2.5)ftime=0}}
  if(e.type==='gift'&&c){const lv=Math.max(0,Math.min(2,e.level|0));if(rstate!=='done')c.boost=Math.min(260,c.boost+BOOST[lv]);feed(c.name,'mandou '+GIFTS[lv]);notify('gift',c.name,lv);if(rstate==='racing'&&lv>=1){fprio=c;if(fage>2.5)ftime=0}}
}
function startRace(){
  if(rstate!=='lobby')return;
  if(cars.length<2){feed('Aviso','precisa de pelo menos 2 carros');return}
  rstate='racing';winner=null;fin=raceX0+LEN;fcar=cars.reduce((a,b)=>b.d>a.d?b:a);ftime=3.5;fn=0;fage=0;fprio=null;fforce=false;raceT=0;goT=1.4;shake=.55;flash=.3;goBurst();sfx('go');
}
function resetRace(){
  cars=[];winner=null;ci=0;rstate='lobby';count=45;fin=null;startX=null;confs=[];
  while(queue.length&&cars.length<MAXC){if(!cars.length)raceX0=cam;startX=raceX0+360;{const q=queue.shift();cars.push(mkCar(q,pref.has(q)?pref.get(q):-1));pref.delete(q)}}
}
function lanesStep(c,dt){
  c.lt-=dt;if(c.lt>0)return;c.lt=.35+Math.random()*.4;
  const ov=(o,m)=>Math.abs((o.d-o.L/2)-(c.d-c.L/2))<(o.L+c.L)/2+m;
  const near=l=>cars.some(o=>o!==c&&o.lane===l&&ov(o,26));
  const front=cars.some(o=>o!==c&&o.lane===c.lane&&o.d>c.d&&(o.d-o.L-c.d)<130&&o.v<c.v+15);
  if(front||Math.random()<.04){
    const o=[c.lane-2,c.lane-1,c.lane+1,c.lane+2].filter(l=>l>=0&&l<NL&&!near(l)&&(Math.abs(l-c.lane)<2||!near((l+c.lane)/2)));
    if(o.length)c.lane=o[Math.random()*o.length|0];
  }
}
function carsStep(dt){
  if(rstate==='lobby'){count-=dt;if(count<=0){if(cars.length>=2)startRace();else count=45}}
  else if(rstate==='racing'){
    raceT+=dt;
    for(const c of cars){
      c.boost*=Math.exp(-dt/5);
      c.v=(c.base*(1+.12*Math.sin(t*1.3+c.ph))+c.boost)*Math.min(1,.15+raceT*.65);
      c.pd=c.d;c.d+=c.v*dt;lanesStep(c,dt);
    }
    for(const c of [...cars].sort((a,b)=>b.d-a.d)){
      let lim=1e9,sp=0;
      if(c.ghost>0){c.ghost-=dt;if(c.ghost<=0&&cars.some(o=>o!==c&&Math.abs(o.y-c.y)<46&&Math.min(o.d,c.d)-Math.max(o.d-o.L,c.d-c.L)>2))c.ghost=.3}
      else for(const o of cars){if(o===c||o.d<=c.pd||Math.abs(o.y-c.y)>46)continue;const l=o.d-o.L-8;if(l<lim){lim=l;sp=o.v}}
      if(c.d>lim){const dv=c.v;c.d=Math.max(lim,c.pd);c.v=Math.min(c.v,sp);c.blk=(c.blk||0)+dt;if(c.blk>.7&&dv>sp+25){c.ghost=1.2;c.blk=0}}else c.blk=0;
      if(c.d>=raceX0+LEN&&!winner)winner=c;
    }
    if(winner){rstate='done';doneT=6;doneAge=0;finalRank=[winner,...[...cars].sort((a,b)=>b.d-a.d).filter(c=>c!==winner)];spawnConfetti();flash=.5;sfx('win');feed(winner.name,'venceu a corrida!');notify('win',winner.name)}
  }else{doneT-=dt;doneAge+=dt;for(const c of cars){c.boost*=Math.exp(-dt*2);c.v*=Math.exp(-dt*2.2);c.d+=c.v*dt}if(doneT<=0)resetRace()}
  for(const c of cars)c.y+=(LANE_Y[c.lane]-c.y)*Math.min(1,dt*4);
  for(const c of cars){c.dw=c.rl?c.v*dt/c.rl:0;c.wa+=c.dw}
  camStep(dt);
  fxStep(dt);
}
function drawCars(){
  const vis=[...cars].sort((a,b)=>a.y-b.y);
  for(const c of vis){
    const sx=c.d-cam,w=c.L,h=w*c.spr.height/c.spr.width;
    if(!c.spr.width||sx<-w-80||sx>W+80)continue;
    const gy=c.y+22;
    g.fillStyle='rgba(0,0,0,.38)';g.beginPath();g.ellipse(sx-w/2,gy,w*.47,6,0,0,7);g.fill();
    const rev=rstate==='lobby'&&cars.length>=2&&count<=3;const bob=rev?Math.sin(t*70+c.ph)*.9:(c.v>40?Math.sin(t*16+c.ph)*(.6+Math.min(1,c.v/650)):0);
    const rot=-Math.min(c.boost,120)/120*.03+Math.max(-.1,Math.min(.1,(LANE_Y[c.lane]-c.y)/60));
    g.save();g.translate(sx-w*.78,gy+bob);g.rotate(rot);if(c.ghost>0)g.globalAlpha=.78;g.drawImage(c.spr,-w*.22,-h,w,h);drawWheels(c,w,h);g.restore();
  }
  g.textBaseline='middle';
  const onscr=vis.filter(c=>{const sx=c.d-cam;return sx>-c.L-80&&sx<W+80});
  let tagSet=null;
  if(onscr.length>14){const top=[...cars].sort((a,b)=>b.d-a.d).slice(0,5);tagSet=new Set([fcar,...top,...onscr.filter(c=>c.boost>30)].filter(Boolean).slice(0,16))}
  const placed=[],TH=40;
  for(const c of [...vis].reverse()){
    const sx=c.d-cam,w=c.L,h=w*(c.spr.height||1)/(c.spr.width||1),gy=c.y+22;
    if(sx<-w-80||sx>W+80)continue;
    if(tagSet&&!tagSet.has(c))continue;
    const nm=fit(c.name,150,F(700,16)),bw=Math.max(128,g.measureText(nm).width+58);
    let bx=sx-w*.8,by=gy-h-TH-6;
    const hit=(a,b)=>a.x<b.x+b.w+4&&a.x+a.w>b.x-4&&a.y<b.y+b.h+4&&a.y+a.h>b.y-4;
    for(let k=0;k<4;k++){const r=placed.find(p=>hit({x:bx,y:by,w:bw,h:TH},p));if(!r)break;bx=r.x+r.w+6}
    if(placed.some(p=>hit({x:bx,y:by,w:bw,h:TH},p)))by-=TH+4;
    bx=Math.max(6,Math.min(W-bw-6,bx));
    placed.push({x:bx,y:by,w:bw,h:TH});
    panel(bx,by,bw,TH,8,c===fcar?GOLD:PBR);
    avatar(bx+21,by+TH/2,12,c);
    txt(nm,bx+41,by+13,F(700,16),'#fff','left',4);
    txt(c.v>1?Math.round(c.v*.45)+' km/h':'—',bx+41,by+30,F(700,14),GOLD,'left',3);
  }
  g.textAlign='center';
  if(rstate==='lobby'&&cars.length<2){const m='Comente para entrar na corrida';g.font=F(700,22);const bw=g.measureText(m).width+48;panel(W/2-bw/2,TOP+LANE*2.5-24,bw,48,12);txt(m,W/2,TOP+LANE*2.5,F(700,22),'#fff','center',0)}
}
const feedEl=document.getElementById('feed');
function feed(u,s){const li=document.createElement('li');li.textContent=u+' '+s;feedEl.prepend(li);while(feedEl.children.length>5)feedEl.lastChild.remove()}
const NAMES=['Lucas','Maria','Duda','Kaua','Bia','Gabi','Rafa','Thiago','Ana','Lari','Dani','Vitor'];
document.getElementById('ctl').addEventListener('click',e=>{
  const a=e.target.dataset.a;if(!a)return;const u=document.getElementById('user').value;
  if(a==='comment')handle({type:'comment',user:u,text:document.getElementById('txt').value});
  if(a==='like')handle({type:'like',user:u,count:15});
  if(a[0]==='g')handle({type:'gift',user:u,level:+a[1]});
  if(a==='rand')for(let i=0;i<5;i++)handle({type:'comment',user:NAMES[Math.random()*NAMES.length|0]+(Math.random()*90+10|0),text:Math.random()<.5?MODELS[Math.random()*MODELS.length|0]:''});
  if(a==='s1')stressJoin();
  if(a==='s2'){storm=12;feed('Teste','chuva de eventos por 12s')}
  if(a==='start'){if(rstate==='lobby'){if(cars.length<2)feed('Aviso','precisa de pelo menos 2 carros');else count=Math.min(count,3)}}
});
window.liveEvent=handle;

// ===== PARTE 3: MINIMAPA E TOP 5 =====
const MPTS=[[20,72],[38,32],[88,16],[138,30],[168,18],[192,50],[170,88],[112,98],[58,102]];
const MAPX=18,MAPY=30;
const mapPath=(()=>{
  const P=MPTS,n=P.length,pts=[];
  const cr=(a,b,c,d,t)=>.5*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t);
  for(let i=0;i<n;i++){
    const p0=P[(i-1+n)%n],p1=P[i],p2=P[(i+1)%n],p3=P[(i+2)%n];
    for(let k=0;k<24;k++){const t=k/24;pts.push([cr(p0[0],p1[0],p2[0],p3[0],t),cr(p0[1],p1[1],p2[1],p3[1],t)])}
  }
  const cum=[0];
  for(let i=1;i<=pts.length;i++){const a=pts[i-1],b=pts[i%pts.length];cum.push(cum[i-1]+Math.hypot(b[0]-a[0],b[1]-a[1]))}
  return{pts,cum,len:cum[pts.length]};
})();
function mapAt(u){
  const L=mapPath.len*Math.min(.9999,Math.max(0,u)),n=mapPath.pts.length;
  let lo=0,hi=n;while(hi-lo>1){const m=(lo+hi)>>1;if(mapPath.cum[m]<=L)lo=m;else hi=m}
  const a=mapPath.pts[lo],b=mapPath.pts[(lo+1)%n],s=(L-mapPath.cum[lo])/((mapPath.cum[lo+1]-mapPath.cum[lo])||1);
  return[a[0]+(b[0]-a[0])*s,a[1]+(b[1]-a[1])*s];
}

// ===== EFEITOS DE VELOCIDADE =====
let camV=0,prevCam=0,parts=[];
const streaks=Array.from({length:26},()=>({x:Math.random()*W,y:TOP+Math.random()*LANE*N,l:40+Math.random()*90,f:.8+Math.random()*.9}));
const hexA=(h,a)=>{const n=parseInt(h.slice(1),16);return'rgba('+(n>>16)+','+(n>>8&255)+','+(n&255)+','+a+')'};
function fxStep(dt){
  stressStep(dt);noteStep(dt);endFx(dt);tickSnd();engStep(dt);
  camV=(cam-prevCam)/Math.max(dt,.001);prevCam=cam;
  for(const s of streaks){s.x-=camV*dt*s.f;if(s.x<-s.l){s.x=W+Math.random()*120;s.y=TOP+Math.random()*LANE*N;s.l=40+Math.random()*90}}
  if(rstate==='racing')for(const c of cars){
    if(c.d-cam<-200||c.d-cam>W+300)continue;
    c.em=(c.em||0)+dt*(5+c.v/60+c.boost*.12)*(LITE?.5:1);
    while(c.em>=1&&parts.length<420){c.em--;parts.push({x:c.d-c.L*.86,y:c.y+19+Math.random()*3,vx:-(15+Math.random()*40),vy:-(10+Math.random()*28),r:2+Math.random()*2,age:0,life:.55+Math.random()*.5,c:c.boost>40?'#cfd8ff':'#d6d6d0'})}
  }
  for(const p of parts){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.r+=dt*9}
  parts=parts.filter(p=>p.age<p.life);
}
function drawFx(){
  const k=LITE?0:Math.max(0,Math.min(1,(camV-280)/420));
  if(k>0){
    g.strokeStyle='#fff';g.lineWidth=2;
    for(const s of streaks){g.globalAlpha=.07+.28*k*(s.f-.6);g.beginPath();g.moveTo(s.x,s.y);g.lineTo(s.x+s.l*(.5+k),s.y);g.stroke()}
  }
  for(const p of parts){g.globalAlpha=Math.max(0,1-p.age/p.life)*.4;g.fillStyle=p.c;g.beginPath();g.arc(p.x-cam,p.y,p.r,0,7);g.fill()}
  g.globalAlpha=1;
}
function drawVignette(){
  const k=Math.max(0,Math.min(1,(camV-300)/400));if(k<.02||LITE)return;
  const gr=g.createRadialGradient(W/2,H/2,H*.25,W/2,H/2,H*.62);
  gr.addColorStop(0,'rgba(0,0,0,0)');gr.addColorStop(1,'rgba(0,0,0,'+(.35*k)+')');
  g.fillStyle=gr;g.fillRect(0,0,W,H);
}

// ===== AVISOS: curtidas, presentes, entradas e vencedor =====
const notes=[];let cur=null;
const NCOL={like:'#ff5fb0',gift:'#ffd23f',join:'#2ee6a6',win:'#ffd23f',queue:'#8fb8ff',swap:'#8fb8ff'};
function notify(type,name,extra){notes.push({type,name,extra});if(notes.length>5)notes.shift();if(type==='like')sfx('like');else if(type==='gift')sfx('gift',extra);else if(type==='join')sfx('join')}
function noteText(n){
  if(n.type==='like')return['CURTIU A LIVE','+'+n.extra+' curtidas · Curtidas aceleram seu veículo.'];
  if(n.type==='gift')return['ENVIOU UM PRESENTE',['Presente pequeno · acelera um pouco.','Presente médio · acelera bastante.','Presente grande · acelera muito!'][n.extra]];
  if(n.type==='join')return['ENTROU NA CORRIDA',(n.extra?n.extra+' · ':'')+'Boa sorte! Curtidas e presentes aceleram seu veículo.'];
  if(n.type==='swap')return['TROCOU DE CARRO','Agora é: '+n.extra+'.'];
  if(n.type==='win')return['VENCEU A CORRIDA!','Uma nova corrida começa em instantes.'];
  return['NA FILA','Entra na próxima corrida.'];
}
function noteStep(dt){
  if(cur){cur.age+=dt;if(cur.age>cur.hold)cur=null}
  if(!cur&&notes.length){cur=notes.shift();cur.age=0;cur.hold=notes.length>3?1.4:3}
}

// ===== CÂMERA DIRETORA: segue um carro de cada vez =====
let fcar=null,ftime=0,fn=0,fage=0,fprio=null,anchor=390,fforce=false;
function camPick(){
  const lead=cars.reduce((a,b)=>b.d>a.d?b:a);
  if(fprio&&cars.includes(fprio)){const c=fprio;fprio=null;fforce=true;return[c,4.5]}
  fprio=null;fforce=false;fn++;
  if(fn%3===0)return[lead,5];
  const pool=cars.filter(c=>c!==lead&&c!==fcar&&lead.d-c.d<900);
  return pool.length?[pool[Math.random()*pool.length|0],4.5]:[lead,5];
}
function camStep(dt){
  if(!cars.length||rstate==='lobby'){fcar=null;return}
  const lead=cars.reduce((a,b)=>b.d>a.d?b:a);
  ftime-=dt;fage+=dt;
  const prev=fcar;
  if(rstate==='done')fcar=winner||lead;
  else if(lead.d>raceX0+LEN-1800)fcar=lead;
  else if(!fcar||ftime<=0||!cars.includes(fcar)||(lead.d-fcar.d>1000&&!fforce)){const r=camPick();fcar=r[0];ftime=r[1]}
  if(fcar!==prev)fage=0;
  anchor+=((fcar===lead?390:280)-anchor)*Math.min(1,dt*3);
  cam+=(fcar.d-anchor-cam)*Math.min(1,dt*(fcar===lead?4:2.4));
}

// ===== LARGADA, CHEGADA E TRANSIÇÃO =====
let goT=0,shake=0,flash=0,raceT=0,confs=[],doneAge=0,finalRank=[];
function goBurst(){
  for(const c of cars){
    if(c.d-cam<-200||c.d-cam>W+300)continue;
    for(let i=0;i<16;i++)parts.push({x:c.d-c.L*.88,y:c.y+17+Math.random()*5,vx:-(70+Math.random()*150),vy:-(12+Math.random()*45),r:3+Math.random()*3,age:0,life:.7+Math.random()*.6,c:'#e0e0da'});
  }
}
function spawnConfetti(){
  const cl=['#ffd23f','#ff5fb0','#2ee6a6','#4aa3ff','#ff7a1a','#ffffff','#b36bff'];
  confs=Array.from({length:170},()=>({x:Math.random()*W,y:-20-Math.random()*320,vx:(Math.random()-.5)*60,vy:90+Math.random()*130,rot:Math.random()*6,vr:(Math.random()-.5)*10,w:5+Math.random()*5,h:8+Math.random()*7,c:cl[Math.random()*cl.length|0],ph:Math.random()*6}));
}
function endFx(dt){
  goT=Math.max(0,goT-dt);shake=Math.max(0,shake-dt*1.1);flash=Math.max(0,flash-dt*.9);
  for(const f of confs){f.x+=(f.vx+Math.sin(t*3+f.ph)*35)*dt;f.y+=f.vy*dt;f.rot+=f.vr*dt}
  confs=confs.filter(f=>f.y<H+30);
  if(rstate==='lobby'&&cars.length>=2&&count<=3)for(const c of cars){
    if(c.d-cam<-200||c.d-cam>W+300)continue;
    c.em2=(c.em2||0)+dt*14;
    while(c.em2>=1&&parts.length<420){c.em2--;parts.push({x:c.d-c.L*.9,y:c.y+19+Math.random()*3,vx:-(30+Math.random()*60),vy:-(8+Math.random()*20),r:2+Math.random()*2,age:0,life:.5+Math.random()*.4,c:'#d6d6d0'})}
  }
}
function drawStartUi(){
  const show=(rstate==='lobby'&&cars.length>=2&&count<=3.05)||goT>0;
  if(!show)return;
  const go=goT>0,n=Math.ceil(count),lit=go?3:Math.max(0,4-n),cx=450,cy=TOP+LANE*2.5;
  g.save();
  panel(cx-80,cy-62,160,124,14);
  for(let i=0;i<3;i++){
    const on=go||i<lit,col=go?'#2ee86b':'#ff3b3b';
    g.fillStyle=on?col:'#2a2f33';g.beginPath();g.arc(cx-46+i*46,cy-28,17,0,7);g.fill();
    if(on){g.shadowColor=col;g.shadowBlur=18;g.fill();g.shadowBlur=0}
  }
  g.textAlign='center';g.textBaseline='middle';g.fillStyle=go?'#2ee86b':'#fff';
  const pulse=go?1+goT*.25:1+(count%1)*.25;
  g.font='700 '+Math.round(44*pulse)+'px system-ui,Arial';
  g.fillText(go?'VAI!':String(Math.max(1,n)),cx,cy+22);
  g.restore();
}
function drawResult(){
  if(rstate!=='done'||!winner)return;
  const a=doneAge,e=Math.min(1,a/.5),eb=1+2.70158*Math.pow(e-1,3)+1.70158*Math.pow(e-1,2),s=.5+.5*eb;
  const cx=W/2,cy=H/2;
  g.save();g.translate(cx,cy);g.scale(s,s);g.globalAlpha=Math.min(1,a/.25);
  panel(-220,-135,440,270,18);
  g.fillStyle='rgba(255,210,63,.85)';g.fillRect(-190,-125,380,2);
  txt('VENCEDOR DA CORRIDA',0,-98,F(700,21),GOLD,'center',0);
  g.fillStyle='#14211f';g.beginPath();g.arc(0,-34,46,0,7);g.fill();
  g.lineWidth=5;g.strokeStyle=GOLD;g.stroke();
  txt(ini(winner.name),0,-33,F(700,46),'#fff','center',0);
  txt('👑',34,6,'38px '+UI,'#fff','center',0);
  let fs=34;g.font=F(700,fs);
  while(g.measureText(winner.name).width>400&&fs>16){fs--;g.font=F(700,fs)}
  txt(winner.name,0,40,F(700,fs),'#fff','center',0);
  txt(winner.cn||'Carro',0,74,F(700,24),'#7be07b','center',0);
  txt('Próxima largada em '+Math.max(1,Math.ceil(doneT))+' s',0,104,F(700,16),'#fff','center',0);
  g.fillStyle='rgba(255,255,255,.15)';g.fillRect(-190,123,380,4);
  g.fillStyle=GOLD;g.fillRect(-190,123,380*Math.max(0,Math.min(1,doneT/6)),4);
  g.restore();
}
function drawConfetti(){
  for(const f of confs){g.save();g.translate(f.x,f.y);g.rotate(f.rot);g.fillStyle=f.c;g.fillRect(-f.w/2,-f.h/2,f.w,f.h);g.restore()}
}

// ===== INTERFACE PADRONIZADA (fontes, cores, bordas) =====
const UI='system-ui,Arial',PBG='rgba(8,24,24,.9)',PBR='rgba(120,200,180,.35)',GOLD='#ffd23f',MUTE='rgba(255,255,255,.72)';
const F=(w,s)=>w+' '+s+'px '+UI;
function panel(x,y,w,h,r,acc){g.fillStyle=PBG;g.beginPath();g.roundRect(x,y,w,h,r);g.fill();g.lineWidth=2;g.strokeStyle=acc||PBR;g.stroke()}
function txt(s,x,y,font,fill,align,ow){
  g.font=font;g.textAlign=align||'left';g.textBaseline='middle';
  if(ow!==0){g.lineJoin='round';g.lineWidth=ow||4;g.strokeStyle='rgba(0,0,0,.85)';g.strokeText(s,x,y)}
  g.fillStyle=fill;g.fillText(s,x,y);
}
function fit(s,mw,font){g.font=font;if(g.measureText(s).width<=mw)return s;while(s.length>2&&g.measureText(s+'…').width>mw)s=s.slice(0,-1);return s+'…'}
function avatar(x,y,r,c){
  g.fillStyle='#14211f';g.beginPath();g.arc(x,y,r,0,7);g.fill();
  g.lineWidth=3;g.strokeStyle=c.color;g.stroke();
  txt(ini(c.name),x,y+1,F(700,r+2),'#fff','center',0);
}
function finishMark(){
  // linha de chegada do minimapa: retângulo quadriculado atravessando a pista
  const a=mapAt(0),b=mapAt(.004),ang=Math.atan2(b[1]-a[1],b[0]-a[0]);
  g.save();g.translate(a[0],a[1]);g.rotate(ang);
  g.fillStyle='rgba(0,0,0,.75)';g.beginPath();g.roundRect(-8,-14.5,16,29,2);g.fill();
  for(let r=0;r<4;r++)for(let c=0;c<2;c++){g.fillStyle=(r+c)%2?'#111':'#fff';g.fillRect(-6+c*6,-12+r*6,6,6)}
  g.restore();
}
function drawHud(){
  if(rstate==='lobby')return;
  const rank=[...cars].sort((a,b)=>b.d-a.d);
  g.save();g.translate(MAPX,MAPY);g.lineJoin='round';
  g.beginPath();mapPath.pts.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.closePath();
  g.strokeStyle='rgba(0,0,0,.6)';g.lineWidth=11;g.stroke();
  g.strokeStyle='#fff';g.lineWidth=6;g.stroke();
  finishMark();
  const span=LEN-330;
  for(let i=Math.min(rank.length,30)-1;i>=0;i--){const c=rank[i],q=mapAt((c.d-(raceX0+330))/span);avatar(q[0],q[1],i?9:11,c)}
  g.restore();
  // TOP 5: colunas fixas (posição, foto, nome, velocidade)
  const pw=230,px=W-pw-10,py=12,rh=28,ph=46+rh*5+8;
  panel(px,py,pw,ph,12);
  txt('TOP 5',px+14,py+21,F(700,17),GOLD,'left',0);
  txt('km/h',px+pw-14,py+21,F(600,12),MUTE,'right',0);
  g.fillStyle=PBR;g.fillRect(px+12,py+37,pw-24,1);
  for(let i=0;i<5;i++){
    const y=py+46+rh*i+rh/2,c=rank[i];
    if(i===0&&c){g.fillStyle='rgba(255,210,63,.14)';g.beginPath();g.roundRect(px+6,y-rh/2+1,pw-12,rh-2,8);g.fill()}
    txt((i+1)+'°',px+14,y,F(700,15),['#ffd23f','#d9dde3','#e0a060'][i]||'#fff','left',3);
    if(c){
      avatar(px+56,y,11,c);
      txt(fit(c.name,pw-76-58,F(700,14)),px+74,y,F(700,14),'#fff','left',3);
      txt(c.v>1?String(Math.round(c.v*.45)):'—',px+pw-14,y,F(700,14),GOLD,'right',3);
    }else txt('—',px+74,y,F(700,14),'rgba(255,255,255,.35)','left',0);
  }
}
function drawNote(){
  if(!cur)return;
  const IN=.35,OUT=.3,a=cur.age,hold=cur.hold,lob=rstate==='lobby';
  const x0=lob?250:10,w=lob?280:520,y=lob?64:214,hh=lob?46:52,s1=lob?14:17,s2=lob?12:14;
  let x=x0,al=1;
  if(a<IN){const e=1-Math.pow(1-a/IN,3);x=x0-(1-e)*(x0+w)}
  else if(a>hold-OUT)al=Math.max(0,(hold-a)/OUT);
  const col=NCOL[cur.type],tx=noteText(cur);
  g.save();g.globalAlpha=al;
  panel(x,y,w,hh,10,col);
  const nm='@'+fit(cur.name,lob?110:200,F(700,s1));
  txt(nm,x+16,y+hh*.33,F(700,s1),col,'left',0);
  g.font=F(700,s1);const nw=g.measureText(nm+' ').width;
  txt(fit('· '+tx[0],w-56-nw,F(700,s1)),x+16+nw,y+hh*.33,F(700,s1),'#fff','left',0);
  txt(fit(tx[1],w-60,F(600,s2)),x+16,y+hh*.74,F(600,s2),MUTE,'left',0);
  txt({like:'❤️',gift:'🎁',join:'🏁',win:'🏆',queue:'⏳',swap:'🚗'}[cur.type],x+w-14,y+hh/2,'20px '+UI,'#fff','right',0);
  g.restore();
}
const MODELS=[...new Set(CARNAME)].length?[...new Set(CARNAME)]:['Carro'];
const mmss=s=>{s=Math.max(0,Math.ceil(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
const _lobbyUiMarker=0;
function drawLobbyUi(){
  if(rstate!=='lobby')return;
  panel(10,10,520,46,12);
  txt('LARGADA EM '+mmss(count),W/2,34,F(700,26),count<=10?'#ff6b5a':GOLD,'center',0);
  panel(10,64,230,40+MODELS.length*24+10,12);
  txt('CARROS DISPONÍVEIS',24,82,F(700,13),GOLD,'left',0);
  MODELS.forEach((m,i)=>txt(m,24,110+i*24,F(600,17),'#fff','left',0));
  panel(10,902,520,48,12);
  txt('COMENTE O NOME DO CARRO PRA ESCOLHER',W/2,919,F(700,17),'#fff','center',0);
  txt('A cor é sorteada',W/2,938,F(600,13),MUTE,'center',0);
}

function drawRoad(){
  const ox=-(cam%TILE),RH=LANE*N,bl=LITE?0:Math.min(16,Math.max(0,(camV-200)*.025));
  g.drawImage(tile,ox,TOP,TILE,RH);g.drawImage(tile,ox+TILE,TOP,TILE,RH);
  if(bl>1){g.globalAlpha=.35;for(const s of[-bl,bl]){g.drawImage(tile,ox+s,TOP,TILE,RH);g.drawImage(tile,ox+TILE+s,TOP,TILE,RH)}g.globalAlpha=1}
  // meio-fio e bordas pintadas
  g.fillStyle='#cfd2d6';g.fillRect(0,TOP-2,W,4);
  let sh=g.createLinearGradient(0,TOP+2,0,TOP+12);sh.addColorStop(0,'rgba(0,0,0,.3)');sh.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=sh;g.fillRect(0,TOP+2,W,10);
  sh=g.createLinearGradient(0,BOT-12,0,BOT);sh.addColorStop(0,'rgba(0,0,0,0)');sh.addColorStop(1,'rgba(0,0,0,.3)');g.fillStyle=sh;g.fillRect(0,BOT-12,W,12);
  g.fillStyle='rgba(0,0,0,.4)';g.fillRect(0,TOP+12,W,2);g.fillStyle='#f0f1ee';g.fillRect(0,TOP+8,W,5);
  g.fillStyle='rgba(0,0,0,.4)';g.fillRect(0,BOT-9,W,2);g.fillStyle='#f0f1ee';g.fillRect(0,BOT-14,W,5);
  // faixas tracejadas (esticam um pouco com a velocidade) e tachões refletivos
  const dx=-(cam%200);
  for(const k of[1,2,4,5]){
    const y=TOP+LANE*k;
    for(let x=dx-200;x<W;x+=200){
      g.fillStyle='rgba(0,0,0,.42)';g.fillRect(x+48-bl,y,104+bl*2,4);
      g.fillStyle='#eceeea';g.fillRect(x+48-bl,y-3,104+bl*2,4.5);
      g.fillStyle='rgba(255,255,255,'+(.55+.35*Math.sin(t*8+x*.05))+')';g.fillRect(x+196,y-2,8,4);
    }
  }
  // linha dupla amarela com tachões amarelos
  g.fillStyle='rgba(0,0,0,.35)';g.fillRect(0,MID-4,W,2);g.fillRect(0,MID+4,W,2);
  g.fillStyle='#f0bf1a';g.fillRect(0,MID-7,W,4);g.fillRect(0,MID+1,W,4);
  const dy=-(cam%100);
  for(let x=dy-100;x<W;x+=100){g.fillStyle='rgba(255,226,90,'+(.6+.4*Math.sin(t*9+x*.07))+')';g.fillRect(x,MID-2,10,4)}
}

// ===== SONS (criados por código, sem arquivos) =====
const snd={ac:null,m:null,on:false,vol:.4,eng:null,noise:null,last:{}};
function sndInit(){
  if(snd.ac)return;
  const A=window.AudioContext||window.webkitAudioContext;if(!A)return;
  const ac=snd.ac=new A(),comp=ac.createDynamicsCompressor();
  snd.m=ac.createGain();snd.m.gain.value=0;snd.m.connect(comp);comp.connect(ac.destination);
  const o1=ac.createOscillator(),o2=ac.createOscillator(),lp=ac.createBiquadFilter(),eg=ac.createGain(),lfo=ac.createOscillator(),lg=ac.createGain();
  o1.type='sawtooth';o2.type='square';lp.type='lowpass';lp.Q.value=2;eg.gain.value=0;
  o1.connect(lp);o2.connect(lp);lp.connect(eg);eg.connect(snd.m);
  lfo.frequency.value=9;lg.gain.value=3;lfo.connect(lg);lg.connect(o1.frequency);lg.connect(o2.frequency);
  o1.start();o2.start();lfo.start();snd.eng={o1,o2,lp,eg};
  const len=Math.floor(ac.sampleRate*2),buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<len;i++)d[i]=Math.random()*2-1;snd.noise=buf;
}
function sndSet(on){
  snd.on=on;if(on)sndInit();
  if(snd.ac){if(on)snd.ac.resume();snd.m.gain.setTargetAtTime(on?snd.vol*.5:0,snd.ac.currentTime,.05)}
}
function tone(f,d,type,v,t0,f2){
  if(!snd.on||!snd.ac)return;
  const ac=snd.ac,o=ac.createOscillator(),gn=ac.createGain(),st=ac.currentTime+(t0||0);
  o.type=type||'sine';o.frequency.setValueAtTime(f,st);if(f2)o.frequency.exponentialRampToValueAtTime(f2,st+d);
  gn.gain.setValueAtTime(.0001,st);gn.gain.exponentialRampToValueAtTime(v||.3,st+.012);gn.gain.exponentialRampToValueAtTime(.0001,st+d);
  o.connect(gn);gn.connect(snd.m);o.start(st);o.stop(st+d+.05);
}
function noiseBurst(d,v,f0,f1,t0){
  if(!snd.on||!snd.ac||!snd.noise)return;
  const ac=snd.ac,src=ac.createBufferSource(),bp=ac.createBiquadFilter(),gn=ac.createGain(),st=ac.currentTime+(t0||0);
  src.buffer=snd.noise;bp.type='bandpass';bp.Q.value=1.2;
  bp.frequency.setValueAtTime(f0,st);bp.frequency.exponentialRampToValueAtTime(f1,st+d);
  gn.gain.setValueAtTime(.0001,st);gn.gain.exponentialRampToValueAtTime(v,st+d*.25);gn.gain.exponentialRampToValueAtTime(.0001,st+d);
  src.connect(bp);bp.connect(gn);gn.connect(snd.m);src.start(st,Math.random());src.stop(st+d+.05);
}
const SFX={
  tick(){tone(520,.13,'square',.16)},
  go(){tone(1040,.7,'square',.18);noiseBurst(.9,.3,400,2600)},
  win(){[523,659,784,1047].forEach((f,i)=>{tone(f,.28,'triangle',.26,i*.13);tone(f*2,.2,'sine',.07,i*.13)});tone(1047,.9,'triangle',.26,.55);tone(1319,.9,'triangle',.16,.55);noiseBurst(2.2,.1,1400,2200,.4)},
  like(){tone(700,.09,'sine',.2,0,1200)},
  gift(lv){const ns=[523,659,784,1047,1319].slice(0,3+(lv|0));ns.forEach((f,i)=>tone(f,.22,'triangle',.2,i*.07));if(lv>=2)noiseBurst(.6,.14,800,4000)},
  join(){tone(660,.06,'sine',.12)}
};
function sfx(n,x){
  const now=performance.now();if(snd.last[n]&&now-snd.last[n]<110)return;
  snd.last[n]=now;if(SFX[n])SFX[n](x);
}
let lastTick=0;
function tickSnd(){
  if(rstate==='lobby'&&cars.length>=2&&count<=3.05){const n=Math.ceil(count);if(n!==lastTick&&n>=1&&n<=3){lastTick=n;sfx('tick')}}
  else if(rstate==='lobby')lastTick=0;
}
function engStep(dt){
  const e=snd.eng;if(!snd.on||!snd.ac||!e)return;
  const t0=snd.ac.currentTime;let v=0,gn=0;
  if(rstate==='racing'||rstate==='done'){
    const f=fcar||cars[0];v=f?f.v:0;
    gn=rstate==='done'?.05*Math.min(1,v/300):.07+Math.min(.07,v/8000);
  }else if(rstate==='lobby'&&cars.length>=2&&count<=3.05){
    v=250+Math.sin(t*22)*60+(3.05-count)*140;gn=.06+(3.05-count)*.03;
  }
  const fq=38+v*.26;
  e.o1.frequency.setTargetAtTime(fq,t0,.08);e.o2.frequency.setTargetAtTime(fq*.5,t0,.08);
  e.lp.frequency.setTargetAtTime(260+v*1.8,t0,.1);e.eg.gain.setTargetAtTime(gn,t0,.12);
}
{
  const sb=document.getElementById('snd'),vs=document.getElementById('vol');
  sb.onclick=()=>{sndSet(!snd.on);sb.textContent=snd.on?'🔊 Som ligado':'🔇 Ativar som'};
  vs.oninput=e=>{snd.vol=e.target.value/100;if(snd.on&&snd.m)snd.m.gain.setTargetAtTime(snd.vol*.5,snd.ac.currentTime,.05)};
}

