let LITE=false,SC=2,storm=0;
const ini=n=>(Array.from(n)[0]||'?').toUpperCase();
const STRESS=['Maria Eduarda Fernandes de Albuquerque','xX_DarkRacer_Xx','🔥Lucas🔥','João Pedro','Ângela Conceição','A','ᴍᴀʀɪᴀ','ΑΛΕΞΑΝΔΡΟΣ','王小明','@@@@####','pedro_isaque_goncalves_bezerra_2026','Jeferson Matheus'];
function stressJoin(){
  const base=['Lucas','Maria','Duda','Kaua','Bia','Gabi','Rafa','Thiago'];
  for(let i=0;i<100;i++)handle({type:'comment',user:i<STRESS.length?STRESS[i]:base[i%8]+(i*7%100)});
  feed('Teste','100 entradas de uma vez');
}
function stressStep(dt){
  if(storm<=0)return;
  storm-=dt;
  const n=Math.floor(dt*30+Math.random()),pool=cars.length?cars:[{name:'Teste'}];
  for(let i=0;i<n;i++){
    const u=pool[Math.random()*pool.length|0].name;
    handle(Math.random()<.5?{type:'like',user:u,count:1+(Math.random()*20|0)}:{type:'gift',user:u,level:Math.random()*3|0});
  }
}
function setLite(on){LITE=on;SC=on?1:2;cv.width=540*SC;cv.height=960*SC}
const perfEl=document.getElementById('perf');
let pT=0,pF=0,pMin=999,pWorst=0,pShow=0;
function perfTick(n,ms){
  pF++;pWorst=Math.max(pWorst,ms);if(ms>0)pMin=Math.min(pMin,1000/ms);
  if(n-pT>=500){
    perfEl.textContent='FPS '+Math.round(pF*1000/(n-pT))+' (mín '+Math.round(pMin)+') · pior quadro '+Math.round(pWorst)+' ms · carros '+cars.length+' · fila '+queue.length+' · partículas '+parts.length;
    pT=n;pF=0;if(n-pShow>5000){pMin=999;pWorst=0;pShow=n}
  }
}
document.getElementById('lite').onchange=e=>setLite(e.target.checked);

// ===== RODAS GIRANDO =====
const WC=[];
function wheelCrops(k){
  if(WC[k])return WC[k];
  const im=imgs[k],w=CARWH[k];
  if(!w||!im||!im.width)return null;
  WC[k]=w.map(([x,y,r])=>{const c=document.createElement('canvas');c.width=c.height=Math.ceil(2*r);const p=c.getContext('2d');p.beginPath();p.arc(r,r,r*.96,0,7);p.clip();p.drawImage(im,x-r,y-r);return c});
  return WC[k];
}
function drawWheels(c,w,h){
  const wc=wheelCrops(c.k);if(!wc)return;
  const s=w/c.spr.width,wh=CARWH[c.k],gh=c.ghost>0?.78:1,n=LITE?1:Math.min(8,Math.max(1,Math.ceil(c.dw/.14)));
  for(let j=0;j<2;j++){
    const x=wh[j][0],y=wh[j][1],R=wh[j][2]*s;
    g.save();g.translate(-w*.22+x*s,-h+y*s);
    for(let q=0;q<n;q++){g.save();g.globalAlpha=gh/(q+1);g.rotate(c.wa-q*c.dw/n);g.drawImage(wc[j],-R,-R,2*R,2*R);g.restore()}
    g.restore();
  }
}

// ===== ESCOLHA DO CARRO PELO COMENTÁRIO (só o modelo, a cor é sorteada) =====
const pref=new Map();
const MODEL_K=MODELS.map(m=>CARNAME.map((n,k)=>n===m?k:-1).filter(k=>k>=0));
const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function modelFrom(text){
  if(!CARNAME.length||!text)return -1;
  const t=' '+norm(text).replace(/[^a-z0-9]+/g,' ')+' ';
  for(let m=0;m<MODELS.length;m++)if(t.includes(' '+norm(MODELS[m])+' '))return m;
  return -1;
}

let last=performance.now();
function loop(n){
  const ms=n-last,dt=Math.min(.05,ms/1000);last=n;t+=dt;perfTick(n,ms);
  if(!cars.length&&!paused)cam+=speed*dt;
  carsStep(dt);draw();requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

document.getElementById('sp').oninput=e=>{speed=+e.target.value;document.getElementById('spv').textContent=speed};
document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Continuar':'Pausar'};
document.getElementById('fin').onclick=()=>{fin=cam+W+60};